CREATE POLICY "owner media read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'blog-media' AND private.is_owner()); CREATE POLICY "owner media upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'blog-media' AND private.is_owner()); CREATE POLICY "owner media update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'blog-media' AND private.is_owner()) WITH CHECK (bucket_id = 'blog-media' AND private.is_owner()); CREATE POLICY "owner media delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'blog-media' AND private.is_owner());